script.setup:
const { device } = ctx;
const N = 200000;
const u = ctx.utils.createUniforms();
// Particles: xy position, zw velocity, scattered in a disc.
const data = new Float32Array(N * 4);
for (let i = 0; i < N; i++) {
  const a = Math.random() * Math.PI * 2, r = Math.sqrt(Math.random()) * 0.9;
  data[i * 4] = Math.cos(a) * r;
  data[i * 4 + 1] = Math.sin(a) * r;
}
const particles = device.createBuffer({ size: data.byteLength, usage: GPUBufferUsage.STORAGE | GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST });
device.queue.writeBuffer(particles, 0, data);

const code = u.wgsl + `
@group(0) @binding(0) var<uniform> U: Uniforms;
@group(0) @binding(1) var<storage, read_write> P: array<vec4f>;

fn flow(p: vec2f, t: f32) -> vec2f {
  let a = sin(p.y * 3.1 + t * 0.7) + cos(p.x * 2.3 - t * 0.5);
  let b = cos(p.x * 3.7 - t * 0.6) - sin(p.y * 2.9 + t * 0.4);
  return vec2f(a, b);
}

@compute @workgroup_size(64)
fn step(@builtin(global_invocation_id) id: vec3u) {
  let i = id.x;
  if (i >= arrayLength(&P)) { return; }
  let aspect = U.resolution.x / U.resolution.y;
  var p = P[i];
  var v = p.zw * 0.96 + flow(p.xy * U.u_scale, U.time) * 0.0009 * U.u_speed;
  // While the mouse is pressed, particles are pulled toward it.
  if (U.mouse.z > 0.0) {
    let m = vec2f((U.mouse.x / U.resolution.x * 2.0 - 1.0) * aspect, U.mouse.y / U.resolution.y * 2.0 - 1.0);
    let d = m - p.xy;
    v += normalize(d + vec2f(1e-5)) * 0.0006 / (0.05 + length(d));
  }
  p = vec4f(p.xy + v, v);
  if (abs(p.x) > 1.2 * aspect || abs(p.y) > 1.2) { p = vec4f(p.xy * -0.5, 0.0, 0.0); }
  P[i] = p;
}

struct VOut {
  @builtin(position) pos: vec4f,
  @location(0) speed: f32,
}

@vertex
fn vs(@location(0) p: vec4f) -> VOut {
  let aspect = U.resolution.x / U.resolution.y;
  var o: VOut;
  o.pos = vec4f(p.x / aspect, p.y, 0.0, 1.0);
  o.speed = length(p.zw) * 120.0;
  return o;
}

@fragment
fn fs(i: VOut) -> @location(0) vec4f {
  let c = mix(U.u_cold, U.u_hot, clamp(i.speed, 0.0, 1.0));
  return vec4f(c * U.u_glow, 1.0);
}
`;
const module = await ctx.utils.createShaderModule(code, "particles");
const compute = device.createComputePipeline({ layout: "auto", compute: { module, entryPoint: "step" } });
const additive = { srcFactor: "one", dstFactor: "one", operation: "add" };
const render = device.createRenderPipeline({
  layout: "auto",
  vertex: { module, entryPoint: "vs", buffers: [{ arrayStride: 16, attributes: [{ shaderLocation: 0, offset: 0, format: "float32x4" }] }] },
  fragment: { module, entryPoint: "fs", targets: [{ format: ctx.format, blend: { color: additive, alpha: additive } }] },
  primitive: { topology: "point-list" },
});
ctx.state.N = N;
ctx.state.u = u;
ctx.state.particles = particles;
ctx.state.compute = compute;
ctx.state.render = render;
ctx.state.computeGroup = device.createBindGroup({ layout: compute.getBindGroupLayout(0), entries: [{ binding: 0, resource: { buffer: u.buffer } }, { binding: 1, resource: { buffer: particles } }] });
ctx.state.renderGroup = device.createBindGroup({ layout: render.getBindGroupLayout(0), entries: [{ binding: 0, resource: { buffer: u.buffer } }] });

script.render:
const s = ctx.state, device = ctx.device;
s.u.update();
const enc = device.createCommandEncoder();
const cp = enc.beginComputePass();
cp.setPipeline(s.compute);
cp.setBindGroup(0, s.computeGroup);
cp.dispatchWorkgroups(Math.ceil(s.N / 64));
cp.end();
const rp = enc.beginRenderPass({
  colorAttachments: [{ view: ctx.context.getCurrentTexture().createView(), clearValue: { r: 0.01, g: 0.01, b: 0.02, a: 1 }, loadOp: "clear", storeOp: "store" }],
});
rp.setPipeline(s.render);
rp.setBindGroup(0, s.renderGroup);
rp.setVertexBuffer(0, s.particles);
rp.draw(s.N);
rp.end();
device.queue.submit([enc.finish()]);
ctx.publish("particles", s.N);
